target_user = "xiaoqy"
keywords = ["ocean", "spectre", "virtuoso"]

def kill_spectre_ocean():
    for kw in keywords:
        ps = subprocess.run(
            ["pgrep", "-u", target_user, kw],
            stdout=subprocess.PIPE, text=True
        )
        for pid in ps.stdout.strip().split("\n"):
            if pid:
                subprocess.run(["kill", "-9", pid])
                print(f"[KILL] {kw} PID {pid}")

def run_fre(short_hash_scs_filename, ocean_netlist):
    try:
        ocean_path = f"/home/imsic/xiaoqy/pyrylen/ocean/{short_hash_scs_filename}.ocean"

        with open(ocean_path, "w") as ocean_file:
            ocean_file.write(ocean_netlist)

        spectre_cmd = f"source /home/imsic/zhangwx/EDA/env_config/env_spectre191_alpsnew_IC618new && ocean -nograph -restore /home/imsic/xiaoqy/pyrylen/ocean/{short_hash_scs_filename}.ocean -f psfascii"
        result = subprocess.run(spectre_cmd,shell=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120,check=True)
        stdout_str = result.stdout.decode("utf-8", errors="ignore")
        stderr_str = result.stderr.decode("utf-8", errors="ignore")
        if result.returncode != 0:
            raise RuntimeError(f"returncode: {result.returncode} file: {ocean_path}")
        combined_output = stdout_str + "\n" + stderr_str
        # print(combined_output)
        pin = re.search(r"pin=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*", combined_output)

        if pin:
            print(pin)
        else:
            pin = 0
        return pin
    except subprocess.CalledProcessError as e:
        print("simerror")
        print(e.stderr.decode(errors="ignore"))
        pin = 0
        return pin
    except subprocess.TimeoutExpired:
        print("timeout")
        pin = 0
        return pin
    finally:
        kill_spectre_ocean()
        os.system(f"rm -rf /home/imsic/xiaoqy/pyrylen/ocean/{short_hash_scs_filename}*")
        os.system(f"rm -rf /home/imsic/xiaoqy/simulation/test_rec_com/spectre/schematic/psf")
        os.system(f"rm -rf /home/imsic/xiaoqy/*.log")
        os.system(f"rm -rf /home/imsic/xiaoqy/CDS.log.*")
        os.system(f"rm -rf /home/imsic/xiaoqy/CDS.log.*.cdslck")

def run_spectre_safe(short_hash_scs_filename, spectre_netlist, Pin):
    try:
        cwd = os.getcwd()
        scs_path = f"/home/imsic/xiaoqy/pyrylen/spectre_netlist_path/{short_hash_scs_filename}.scs"
        raw_path = f"/home/imsic/xiaoqy/pyrylen/spectre_netlist_path/{short_hash_scs_filename}.raw/hb.fd.pss_hb"

        with open(scs_path, "w") as netlist_file:
            netlist_file.write(spectre_netlist)

        spectre_cmd = f"source /home/imsic/zhangwx/EDA/env_config/env_spectre191_alpsnew_IC618new && spectre /home/imsic/xiaoqy/pyrylen/spectre_netlist_path/{short_hash_scs_filename}.scs -f psfascii"
        result = subprocess.run(spectre_cmd, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        if result.returncode != 0:
            raise RuntimeError(f"returncode: {result.returncode} file: {scs_path}")
        if not os.path.exists(raw_path):
            raise FileNotFoundError(f"no file: {raw_path}")
        with open(raw_path, "r") as psf:
            psf_content = psf.read()
        parsed_data = parse_freq_data(psf_content)
        vload = parsed_data[0]["VLOAD"]
        # print(eta_total)
        return vload
    except Exception as e:
        # print(f"[simwrong] give{e}")
        return 0
    finally:
        os.system(f"rm -rf /home/imsic/xiaoqy/pyrylen/spectre_netlist_path/{short_hash_scs_filename}*")


def parse_freq_data(text):
    block_pattern = re.compile(
        r'(?i)"freq"\s+([\d.e+-]+)\s*((?:.*?(?=\s*"freq"|\s*END|\s*end|\Z))+)',
        re.DOTALL
    )
    blocks = []
    for match in block_pattern.finditer(text):
        freq = float(match.group(1))
        content = match.group(2).strip()
        blocks.append((freq, content))
    result = []
    for freq, content in blocks:
        current = {"freq": freq}
        for line in content.split('\n'):
            line = line.strip()
            if not line:
                continue
            # print(line)
            key = line.strip("\"").split("\"")[0].strip()
            valuestr = line.strip("\"").split("\"")[1].strip().strip("(").strip(")")
            value = complex(float(valuestr.split()[0]), float(valuestr.split()[1]))
            current[key] = value
        result.append(current)
    return result





