def Rect_Opt_Flow(xnorm:list):
    pin, vload = exe_spectre_woxfmr(xnorm)
    result_list = []
    with open("/home/imsic/xiaoqy/pyrylen/result_hv.csv", mode="a+") as f:
        f.write(
            f"{int(xnorm[0])}, {xnorm[1]},{xnorm[2]}, {pin}, "
            f"{vload}\n")
    result_list.append(-pin)
    lower_violation = max(0.0, 1.0 - vload)
    upper_violation = max(0.0, vload - 1.2)
    penalty = lower_violation+upper_violation
    result_list.append(-penalty)
    return result_list


